userAuthInstance.on('result', {
            onResult(result) {
                userAuthInstance.off('result');
                if (result.result===AUTH_ERROR_CODE.AUTH_SUCCESS) {
                    resolve(result.token);
                } else {
                    reject(result.result);
                }
            }
        })

connection.hasDefaultNet((error: BusinessError, data: Object) => {
        if (!data) {
          Logger.error(TAG, 'The default data network is disconnected ' + JSON.stringify(error));
          promptAction.showToast({
            message: $r('app.string.network_error_msg')
          });
          reject({ code: ErrorCode.ERROR_NETWORK_CONNECT_FAILED, message: 'The network seems to have deserted' });
          return;
        }

        cloud.callFunction({
          name: trigger,
          version: '$latest',
          timeout: 2000,
          params: params
        }).then((functionResult: FunctionResult) => {
          Logger.info(TAG, 'Request call success--------' + trigger + ':' + JSON.stringify(functionResult));
          resolve(functionResult.getValue().data);
        }).catch((error: RejectError) => {
          if (times && times > 0) {
            Logger.error(TAG, 'retry times--------' + (MAX_RETRIES - times + 1));
            resolve(request.performRequest(trigger, params, times - 1));
          } else {
            Logger.error(TAG, 'reject error--------' + JSON.stringify(error));
            reject(error);
          }
        });
      })

controller.executeRequest(authRequest, (err, data) => {
        if (err) {
          Logger.error(TAG, 'auth fail,error: ' + JSON.stringify(err));
          this.showLoginFiledToast();
          return;
        }
        let authorizationWithHuaweiIDResponse = data as authentication.AuthorizationWithHuaweiIDResponse;
        let state = authorizationWithHuaweiIDResponse.state;
        if (state != undefined && authRequest.state != state) {
          Logger.error(TAG, 'auth fail,The state is different: ' + JSON.stringify(authorizationWithHuaweiIDResponse));
          this.showLoginFiledToast();
          return;
        }
        Logger.info(TAG, 'auth success: ' + JSON.stringify(authorizationWithHuaweiIDResponse));
        let authorizationWithHuaweiIDCredential = authorizationWithHuaweiIDResponse.data!;
        this.userAccount.portrait = authorizationWithHuaweiIDCredential.avatarUri || '';
        this.userAccount.nickname = authorizationWithHuaweiIDCredential.nickName || '';
        this.handleHWLogin();
      })

controller.executeRequest(loginRequest, (err, data) => {
        if (err) {
          Logger.error(TAG, 'login fail, error' + JSON.stringify(err));
          this.showLoginFiledToast();
          return;
        }
        let loginWithHuaweiIDResponse = data as authentication.LoginWithHuaweiIDResponse;
        let state = loginWithHuaweiIDResponse.state;
        if (state != undefined && loginRequest.state != state) {
          Logger.error(TAG, 'login fail,The state is different: ' + JSON.stringify(loginWithHuaweiIDResponse));
          this.showLoginFiledToast();
          return;
        }
        Logger.info(TAG, 'login success, ' + JSON.stringify(loginWithHuaweiIDResponse));

        let loginWithHuaweiIDCredential = loginWithHuaweiIDResponse.data!;
        this.userAccount.unionId = loginWithHuaweiIDCredential.unionID;
        this.login();
      })

identifier.getOAID((err: BusinessError, data) => {
                  if (err.code) {
                    Logger.error(TAG, `get oaid failed, code: ${err.code}, message: ${err.message}`);
                  } else {
                    this.message = data;
                    this.buttonStatus = false;
                    Logger.info(TAG, `get oaid by callback success`);
                  }
                })

controller.executeRequest(cancelRequest, (error: BusinessError<Object>, data) => {
        if (error) {
          LoginUtils.onCancelSuccess();
          return;
        }
        const cancelAuthorizationResponse = data as authentication.CancelAuthorizationResponse;
        const state = cancelAuthorizationResponse.state;
        if (state && cancelRequest.state !== state) {
          Logger.error(TAG, `Failed to cancel. The state is different, response state: ${state}`);
          LoadingDialogUtil.close()
          return;
        }
        Logger.info(TAG, 'Succeeded in canceling.');
        LoginUtils.onCancelSuccess();
      })

